package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamKandyanCoreBank2 {
    private const val T = "උඩරට නර්තන සම්ප්‍රදාය, වෙස් ඇඳුම හා සරඹ"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උඩරට පා සරඹ 12 අතරින් පාදයක් ඔසවා අනෙක් පාදය අසලින් තබා පනිමින් පුහුණු වන සරඹ රටාව කුමක්ද?", "පැනුම් පා සරඹ", "නිශ්චල සරඹ", "හිඳගෙන කරන සරඹ", "දෑත් ඔසවන සරඹ", "පස්වන හා හයවන පා සරඹවලදී තාලයට පැන පාද මාරු කිරීම පුහුණු කෙරේ."),
        q("උඩරට ගොඩ සරඹවලදී භාවිත කරන 'සම හස්තය' හා 'උඩු අත' මගින් අත් චලන සිදු කරන්නේ කුමන මට්ටමකදීද?", "පපුව සහ උරහිස් මට්ටමේ සිට හිසට ඉහළට", "දණහිස් මට්ටමෙන් පහළට පමණි", "පිටුපසට බැඳ තබාගෙන", "සාක්කු තුළ දමාගෙන", "දෑත් අඩ කවාකාරව පපුව හා උරහිස් මට්ටමේ සිට ඉහළට ගෙන යාම උඩරට ශෛලියයි."),
        q("උඩරට නර්තන ශිල්පියා පළඳින 'සිළම්බු' නමැති පාද ආභරණය සාදා ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "කුහර සහිත පිත්තල හෝ රිදී ලෝහයෙන්", "ලී කැබලිවලින්", "රබර් පටිවලින්", "කපු නූල්වලින්", "ඇතුළත කුඩා ගල් කැට හෝ ලෝහ කැබලි දමා සාදන සිළම්බු පාද සමඟ හඬ නඟයි."),
        q("කොහොඹා කංකාරියේදී 'නෛයන්ඩි' නැට්ටුවන් හා 'වෙස්' නැට්ටුවන් අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "නෛයන්ඩි නැට්ටුවන් වෙස් තට්ටුව නොපැළඳ සුදු ජටාවක් පමණක් පැළඳීම", "නෛයන්ඩි නැට්ටුවන් යක් බෙරය වැයීම", "වෙස් නැට්ටුවන් කෝලම් මුහුණු දැමීම", "නෛයන්ඩි නැට්ටුවන් නැටීමෙන් වැළකීම", "වෙස් තට්ටුව පැළඳීමට අවසර නැති හෝ ඊට පෙර අවස්ථාවල නෛයන්ඩි ඇඳුම භාවිත වේ."),
        q("උඩරට 'උඩැක්කි' නැටුම ආරම්භයේදී සාම්ප්‍රදායිකව ගායනා කරනු ලබන ශ්ලෝක හා කවි මගින් කුමන දෙවියෙකුට නමස්කාර කෙරේද?", "ඊශ්වර සහ විෂ්ණු දෙවියන්ට", "ග්‍රීක සියුස් දෙවියන්ට", "ඊජිප්තු රා දෙවියන්ට", "නෝර්ස් තෝර් දෙවියන්ට", "උඩැක්කිය ශිව (ඊශ්වර) දෙවියන්ගේ ඩමරුව හා සම්බන්ධ යැයි විශ්වාස කෙරේ."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාස මාලාව තුළ ඇති සම්පූර්ණ සරඹ සංඛ්‍යාව කීයද?", "දොළහකි (12)", "හයකි (6)", "විසිහතරකි (24)", "තිහකි (30)", "පා සරඹ 12 ක් සහ ගොඩ සරඹ 12 ක් ලෙස උඩරට මූලික පුහුණුව සකස් වී ඇත."),
        q("උඩරට වෙස් ඇඳුමේ උඩුකය අලංකාර කරන අවුල්හැරයට පිටුපසින් හා ඉදිරියෙන් සවි කරන වටකුරු පිත්තල තහඩුව කුමක්ද?", "පපු තහඩුව හෙවත් මාල පදක්කම", "හවඩිය", "සිළම්බුව", "ජටා පටිය", "පපුව මැද දිදුලන විශාල ලෝහමය පදක්කම වෙස් ඇඳුමේ අවුල්හැරය සම්බන්ධ කරයි."),
        q("වෙස් නැට්ටුවාගේ නළල් පටියට ඉහළින් පෙළට සවි කර ඇති කුඩා රිදී පැහැති ගෝලාකාර කැබලි හඳුන්වන්නේ කෙසේද?", "බුබුළු", "දැති", "පත්", "සිළු", "නළල වටා බුබුළු පෙළක් ලෙස දිලිසෙන කුඩා ගෝල සවි කර තිබේ."),
        q("උඩරට සම්ප්‍රදායේ 'නෛයන්ඩි' ඇඳුමේ ප්‍රධාන වර්ණය වන්නේ කුමක්ද?", "සුදු පැහැය", "තද කළු පැහැය", "තැඹිලි පැහැය", "කොළ පැහැය", "සුදු තලප්පාවක් හා සුදු රැළි රෙද්දක් සමඟ පබළු මාල නෛයන්ඩි ඇඳුමේදී පළඳියි."),
        q("උඩරට නර්තනයේදී පාදය පොළොවට තැබීමේදී ඇති වන ප්‍රධාන තාල ශබ්දයට පූරකයක් වන්නේ කුමක්ද?", "දෙපයේ සිළම්බු හා ගෙජ්ජි නාදය", "අත්පුඩි ශබ්දය", "විසිල් නාදය", "පාවහන් අඩියේ ශබ්දය", "නැට්ටුවා පාද තබන සෑම අවස්ථාවකම සිළම්බු හඬ බෙර තාලයට එක් වේ."),
        q("උඩරට පා සරඹ පුහුණු වීම සඳහා යොදාගන්නා දණ්ඩියම් කඳ සවි කළ යුතු නිවැරදි උස කුමක්ද?", "ශිෂ්‍යයාගේ ඉණ මට්ටමට ආසන්න උසකින්", "පොළොව මට්ටමේම", "හිසට අඩි තුනක් ඉහළින්", "දණහිස් මට්ටමෙන් පහළ", "ඉණ මට්ටමට දණ්ඩියම තිබීමෙන් කොන්ද කෙළින් තබා මණ්ඩි නැමීමට පහසු වේ."),
        q("උඩරට 'පන්තේරු' නැටුමේදී පන්තේරුව වාදනය කරන්නේ කුමන ආකාරයටද?", "අත්ලට හා ඇඟිලිවලට ගටමින් සහ සොලවමින්", "කෝටුවකින් තදින් පහර දෙමින්", "මුවින් පිඹීමෙන්", "බිම මත තබා පාදයෙන් පෑගීමෙන්", "වළල්ලේ ඇති පිත්තල පෙති සෙලවීමෙන් හා අතේ ගැටීමෙන් තාල නාද උපදවයි."),
        q("උඩරට නැටුමේදී 'තීර්මාන' පද වාදනය කිරීමෙන් පසු නැට්ටුවා ගනු ලබන අවසාන ඉරියව්ව කුමක්ද?", "ස්ථාවර මණ්ඩි ඉරියව්වෙන් නිශ්චල වීම", "වේදිකාව මත හිඳගැනීම", "පිටුපස හැරී බැලීම", "අත් දෙක පහළ දමා හිස නැමීම", "සෑම නැටුම් කොටසක්ම මණ්ඩි ඉරියව්වෙන් ස්ථාවරව නැවතීම සම්ප්‍රදායික අලංකාරයකි."),
        q("උඩරට සරඹ අභ්‍යාසවලදී 'තක්කඩ' යන ශබ්ද අනුකරණයෙන් පෙන්වන පාද චලනය කුමක්ද?", "වේගයෙන් පිට පිට දෙවරක් හෝ තුන්වරක් පාදය ගැසීම", "සෙමින් පියවර එකක් තැබීම", "පසුපසට ඇවිදීම", "නිශ්චලව සිටගෙන සිටීම", "මෙම තියුණු පාද චලන බෙර පද සමඟ තරගකාරී ලෙස සමපාත වේ."),
        q("වෙස් නැට්ටුවෙකු සිය නැටුම අවසන් කිරීමේදී බෙරකරුට හා ප්‍රේක්ෂකයන්ට දක්වන ගෞරව සංඥාව කුමක්ද?", "සුරත් නමස්කාරය හෙවත් දෙඅත් එක් කොට ආචාර කිරීම", "වෙස් තට්ටුව ගලවා පෙන්වීම", "වේදිකාවෙන් දුව යාම", "හිස පහත් නොකර සිටීම", "නැටුම අවසානයේ සභාවට හා වාදක මණ්ඩලයට ආචාර කිරීම උසස් විනයකි."),
        q("උඩරට සම්ප්‍රදායේ 'වන්නමක' නැටුමට අමතරව ගායනය කෙරෙන කවි කොටස හඳුන්වන්නේ කුමන නමකින්ද?", "කවිය හා තානම", "සන්නි විලාපය", "පාලි ගීතය", "කෝලම් දෙබස", "සෑම වන්නමක්ම තානම, කවිය, කස්තිරම, සීරුමාරුව සහ අඩව්ව යන අංගවලින් සමන්විත වේ."),
        q("උඩරට නැටුමේදී ශිල්පියාගේ දණහිස් හා ඉණ අතර කොටස ආවරණය කරන අමතර සැරසිල්ල කුමක්ද?", "රැළි මාලය සහ උළුදය", "ජටාව", "තෝඩු", "කරපටිය", "උළුදය මැදින් වැටී ඇති අතර දෙපස රැළි මාලය ඉණට පළල් පෙනුමක් ලබා දෙයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අතරින් ශරීරය දෙපසට හරවා කරනු ලබන චලනවලින් වර්ධනය වන්නේ කුමක්ද?", "ඉණෙහි නම්‍යශීලී බව හා ශරීර භ්‍රමණ පාලනය", "හිසකෙස් වර්ධනය", "කටහඬේ ගැඹුරු බව", "ඇඟිලිවල දිග", "කඳ කෙළින් තබාගෙන ඉණෙන් හැරීම නැටුමේ පැහැදිලි රේඛා මතු කරයි."),
        q("උඩරට නැටුමේදී 'තාලය වැරදීම' වළක්වා ගැනීම සඳහා නැට්ටුවා ප්‍රධාන වශයෙන්ම සවන් දිය යුත්තේ කුමකටද?", "ගැටබෙරයේ වාදනය හා තාලම්පටේ නාදයට", "ප්‍රේක්ෂකයන්ගේ අත්පොළසන් නාදයට", "පසුබිම් සැරසිලිවල සුළං හඬට", "හක්ගෙඩිය පිඹින ශබ්දයට පමණි", "තාලම්පට ස්ථිර ලය පවත්වන අතර ගැටබෙරය පද රටා ඉදිරිපත් කරයි."),
        q("උඩරට 'කොහොඹා කංකාරිය' අවසන් දින උදෑසන ඉදිරිපත් කරන විශේෂිත නැටුමක් කුමක්ද?", "මුවමල නැටුම හෝ ආවැන්දුම", "දහඅට සන්නිය", "සොකරි කෝලම", "රබන් නැටුම", "මංගල යාතුකර්ම අවසානයේ පිං දී ආශිර්වාද කරමින් කංකාරිය නිම කෙරේ."),
        q("උඩරට වෙස් ඇඳුමේ 'පත්' නමැති කොටස සවි කර ඇත්තේ වෙස් තට්ටුවේ කුමන පැත්තකද?", "ඉදිරිපස නළල් පටියට ඉහළින් චාපාකාරව", "කන් දෙකට පහළින්", "බඳ පටියේ පිටුපසින්", "පාදවල වළලුකර අසල", "පත් හත හෝ නවය හිසට කිරුළක පෙනුම හා උසක් ලබා දෙයි."),
        q("උඩරට නැටුමේදී දෙඅත් හිස මට්ටමේ සිට පපුව දක්වා පහළට ගෙන ඒමේදී අත්ල තබා ගත යුතු ආකාරය කුමක්ද?", "ඇඟිලි ලිහිල්ව හා අලංකාරව විහිදාගෙන", "තදින් මිට මොළවාගෙන", "ඇඟිලි සියල්ල පසුපසට නවාගෙන", "අත් දෙක බැඳගෙන", "ලැසි අත් මාරුවේදී ඇඟිලි හා මැණික් කටුව සියුම්ව නම්‍යශීලීව ක්‍රියා කරයි."),
        q("උඩරට නර්තන පුහුණුවේදී 'මණ්ඩි පැනුම්' අභ්‍යාසය වැදගත් වන්නේ ඇයි?", "පිනුම් ගසා නැවත නිවැරදි මණ්ඩි ඉරියව්වෙන් පොළොවට පතිත වීමට", "හිස වටා වෙස් තට්ටුව පැළඳ සිටින විට වේගය අඩු කිරීමට", "තාලම්පට වාදකයාගේ පියවර සංඛ්‍යාව ගණන් කර ගැනීමට", "කවි ගායනය නතර කොට වේදිකාවෙන් ඉවත්ව යාමට", "පිනුමක් අවසානයේ සමබරව මණ්ඩියේ රැඳීම නැටුමේ පාලනය පෙන්වයි."),
        q("උඩරට වන්නම් නැටීමට පෙර කියනු ලබන 'කවිය' තුළ අඩංගු වන්නේ කුමක්ද?", "සත්වයාගේ හෝ සිදුවීමේ වර්ණනාව හා ගුණ කථනය", "ප්‍රේක්ෂකයන්ගේ නම් ලැයිස්තුව", "වාද්‍ය භාණ්ඩ මිල ගණන්", "වේදිකා මානයන්", "වන්නමට අදාළ සත්වයාගේ රූපය හා චර්යාව කවියෙන් වර්ණනා කෙරේ."),
        q("උඩරට නැටුමේදී 'තාලම්පට' වාදනය කරන ශිල්පියා සිටගත යුතු හෝ සිටිය යුතු ස්ථානය කොතැනද?", "ගැටබෙර වාදකයාට ආසන්නව නැටුම් කණ්ඩායමට පෙනෙන ස්ථානයේ", "වේදිකාවෙන් සම්පූර්ණයෙන් පිටත කාමරයක", "නැට්ටුවන්ගේ පාද අතර", "හිස මත තබාගෙන", "තාලම්පට වාදකයා මුළු කණ්ඩායමේම ලය පාලනය කරන මූලික තාල දරන්නාය."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' නිර්මාණය කරනු ලබන ප්‍රධාන ලෝහ මාධ්‍යය කුමක්ද?", "රිදී හෝ රිදී ආලේපිත පිත්තල", "යකඩ හා වානේ", "කළු ගල්", "මැටි", "සුදු පැහැති ඇඳුම් සමඟ රිදී ආභරණ දිලිසීම උඩරට ඇඳුමේ ප්‍රධාන අනන්‍යතාවකි."),
        q("උඩරට නැට්ටුවෙකුගේ 'වළලුකර ශක්තිය' වැදගත් වන ප්‍රධාන අවස්ථාව කුමක්ද?", "පිනුම් ගැසීමේදී හා බඹර කැරකිලිවලදී", "බිම වාඩි වී සිටීමේදී", "කවි පොත් කියවීමේදී", "ආභරණ පෙට්ටියේ තැබීමේදී", "සිරුරේ සම්පූර්ණ බර වළලුකර හරහා පොළොවට වැටෙන විට ආබාධ වළක්වා ගැනීමට ශක්තිය අවශ්‍ය වේ."),
        q("උඩරට පා සරඹ 12 අතර 'තත් ජිත් තොං නං' පදයට අමතරව යෙදෙන තවත් ප්‍රධාන පද කොටසක් කුමක්ද?", "තක දොං තක දොං තරි කිට තොං නං", "හුරේ හුරේ", "සාධු සාධු", "ටික් ටොක්", "විවිධ බෙර පද අනුකරණයන් සරඹ පියවරවල වේගය හා රටාව තීරණය කරයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාස මාලාව තුළ 'දෑත් ඉහළට විහිදුවා කරකැවීම' හඳුන්වන්නේ කුමන නමකින්ද?", "අත් මාරුව හා සිරුර කැරකැවීම", "පාද බැඳීම", "වෙස්මුහුණු සෙලවීම", "කඩු කරකැවීම", "දෑත් ඉහළින් කැරකැවීම හරහා උඩුකයේ ලාලිත්‍යය ඉස්මතු වේ."),
        q("උඩරට නර්තන කලායතනවල 'වෙස් මංගල්‍යය' සඳහා සුදුසු නැකැත් වේලාවක් බලනු ලබන්නේ ඇයි?", "පාරම්පරික ගෞරවය, ශුභ ආරම්භය හා ආශිර්වාදය පතා", "විදුලි ආලෝක පහන් පමණක් පරීක්ෂා කිරීමට", "නැටුම් ශාලාවේ ඉඩකඩ මැන ගැනීමට", "සරඹ අභ්‍යාස පොත් බෙදා දීමට", "ශුභ නැකතින් ගුරුවරයාගේ අතින් වෙස් තට්ටුව පැළඳවීම සාම්ප්‍රදායික චාරිත්‍රයකි."),
        q("උඩරට 'උඩැක්කි' වාද්‍ය භාණ්ඩයෙහි හඬ වෙනස් කිරීම සඳහා ශිල්පියා භාවිත කරන උපක්‍රමය කුමක්ද?", "මැද පටිය අතින් තද කිරීම හා ලිහිල් කිරීම", "ජලය ඉසීම", "කෝටුවකින් තැළීම", "හුළං පිඹීම", "වම් අතින් මැද පටිය තද කරන විට හම ඇදී තියුණු නාදයක් ලැබේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් නැටුම' සඳහා පසුබිම් ගායනයක් ලෙස නොයෙදෙන දෙය කුමක්ද?", "බටහිර ඉංග්‍රීසි පොප් ගීත", "වන්නම් කවි", "කංකාරි යාතිකා", "ප්‍රශස්ති කවි", "උඩරට වෙස් නැටුම දේශීය ශාස්ත්‍රීය කවි හා බෙර පද සමඟ පමණක් ඉදිරිපත් කෙරේ."),
        q("උඩරට නැට්ටුවා 'දෑත් පපුව ඉදිරියට ගෙනැවිත් පිටතට විහිදුවන' චලනය පුහුණු කරන්නේ කුමන සරඹ කොටසේදීද?", "මූලික ගොඩ සරඹ තුළදී", "දිය කැපීමේ මංගල්‍යයේදී", "කෝලම් රංගනයේදී", "සොකරි කමතේදී", "පළමු ගොඩ සරඹ කිහිපයේදී දෑත් නිවැරදි පරාසයක හැසිරවීම උගන්වයි."),
        q("උඩරට සම්ප්‍රදායේ 'කච්චේරි' හෝ 'මඟුල් පෙරහැර' අවස්ථාවලදී ගැටබෙර වාදකයා බෙරය ඉණේ බැඳගෙන වාදනය කරන ඉරියව්ව කුමක්ද?", "සිටගෙන සහ ගමන් කරමින් වාදනය කිරීම", "පැදුරක හිඳගෙන වාදනය කිරීම", "දිගා වී වාදනය කිරීම", "දණ ගසාගෙන වාදනය කිරීම", "උරහිසින් දැමූ වරපටියකින් ගැටබෙරය ඉණේ එල්ලාගෙන ඇවිදිමින් වයනු ලැබේ."),
        q("උඩරට නැටුමේදී 'මණ්ඩිය' බිඳී ගියහොත් සිදු වන ප්‍රධාන නර්තන දෝෂය කුමක්ද?", "නැටුමේ ගාම්භීර බව හා සමබරතාව අඩු වීම", "බෙරයේ හම පැළී යාම", "ඇඳුමේ පැහැය වෙනස් වීම", "වේදිකාවේ ආලෝකය නිවී යාම", "දණහිස් කෙළින් කළහොත් උඩරට නැටුමේ අනන්‍ය ජවසම්පන්න හැඩය ගිලිහී යයි."),
        q("උඩරට නර්තන කලාවේදී 'උරහිස් සමබරතාව' රැකගැනීම සඳහා නැට්ටුවා කළ යුත්තේ කුමක්ද?", "උරහිස් පහළට නොඑල්ලා පළල්ව හා සෘජුව තබා ගැනීම", "උරහිස් ඉදිරියට වකුටු කර ගැනීම", "එක් උරහිසක් ඉහළට ඔසවා තැබීම", "උරහිස් දෙකම සෙලවීමෙන් වැළකීම", "පළල් උරහිස් පිහිටීම නිසා උඩරට අවුල්හැරය හා නැටුම් රේඛා මනාව පෙනේ."),
        q("උඩරට පා සරඹ 12 අතරින් අවසාන පා සරඹ කිහිපයේදී භාවිත වන විශේෂ චලනය කුමක්ද?", "වේගවත් පාද මාරුව සහ පැතිවලට පැනුම්", "දිගා වී නිදාගැනීම", "පාද සෙමින් ඇදගෙන යාම", "දණහිස් බිම තැබීම", "10, 11 හා 12 පා සරඹවලදී නැට්ටුවාට ඉහළ ජවයක් හා පාද වේගයක් ලබා දේ."),
        q("උඩරට වෙස් තට්ටුවේ ඇති 'සිළුමිණ' කොටසේ හැඩය හඳුන්වන්නේ කුමන ආකාරයකින්ද?", "චෛත්‍ය කොතක හෝ නෙළුම් මලක හැඩයට", "හතරැස් පෙට්ටියක හැඩයට", "දිගු ඊතලයක හැඩයට", "වෘත්තාකාර කාසියක හැඩයට", "වෙස් තට්ටුව මුදුනේ ඇති සිළුමිණ මලය රජුගේ කිරුළේ කොත සංකේතවත් කරයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාසවලදී 'පපුවට අත් ගැනීම' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "මැණික් කටුවෙන් නමා දෙඅත් පපුව අසලට ගෙන විහිදුවීම", "දෙඅත් මිට මොළවා පපුවට තදින් ගසා ගැනීම", "දෙඅත් පිටුපස කොන්ද දෙසට ගෙන බැඳ තැබීම", "දෙඅත් පහත හෙළා බිම ස්පර්ශ කර නැගිටීම", "භාවමය හා රිද්මමය සම්බන්ධතාව ගොඩ සරඹ අත් චලනවලින් ප්‍රකට වේ."),
        q("උඩරට 'උඩැක්කිය' වාද්‍ය භාණ්ඩයෙහි බඳ කොටස නිමවා ඇති හැඩය කුමක්ද?", "දෙපස පළල් වී මැද සිහින් වූ වැලි හෝරා යන්ත්‍රයක හැඩය", "සෘජුකෝණාස්‍රාකාර පෙට්ටියක හැඩය", "ගෝලාකාර කළයක හැඩය", "සිලින්ඩරාකාර දිග බටයක හැඩය", "මැදින් සිහින් බැවින් අතට ගෙන මැද පටිය තද කිරීමට හා ලිහිල් කිරීමට පහසුය."),
        q("උඩරට 'පන්තේරු' නැටුම සඳහා සුදුසුම කණ්ඩායම් සැකැස්ම කුමක්ද?", "සමාන නිපුණත්වයක් ඇති නැට්ටුවන් හතරක්, හයක් හෝ අටක් ලෙස", "තනි වාදකයෙකු නිදා සිටීම", "සිය ගණනක් පොදි ගැසී සිටීම", "නැට්ටුවන් ඉවත් කර බෙර පමණක් තැබීම", "යුගල හෝ සමූහ රටා මවමින් පන්තේරු හුවමාරු කිරීම ප්‍රේක්ෂක සිත් ඇදගනී."),
        q("උඩරට වෙස් ඇඳුමේ 'දෙවුර මාලය' හෙවත් 'බෙල්ලේ ආභරණ' අතර පළඳින රතු රෙදි පටිය කුමක්ද?", "කර පටිය හා උරහිස් පටිය", "සිළම්බු පටිය", "දණහිස් පටිය", "පාද ආවරණය", "රිදී පබළු හා රතු රෙදි පසුබිම වෙස් නැට්ටුවාගේ උඩුකය අලංකාර කරයි."),
        q("උඩරට නැටුමේදී 'තාලම්පට' ගැසීමේදී ශිල්පියා පවත්වා ගන්නා නාද දෙක මොනවාද?", "විවෘත දිගු නාදය සහ තද කළ කෙටි නාදය", "සීරු හඬ සහ හුළං හඬ", "බෙර හඬ සහ නළා හඬ", "ගීත හඬ සහ වයලීන් හඬ", "'තිත්' හා 'තා' ලෙස පැහැදිලිව නාද පිට කරමින් තාලම්පට වයනු ලැබේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' ඇඳීමෙන් පසු නැට්ටුවා නොකළ යුතු අවිනීත ක්‍රියාවක් කුමක්ද?", "පාවහන් පැළඳීම හෝ අසුන්වල අසංවරව හිඳ ගැනීම", "කවි ගායනා කිරීම", "මණ්ඩි ඉරියව්වේ සිටීම", "දෙවියන්ට වැඳීම", "වෙස් ඇඳුමේ ගෞරවය හා විනය රැකීම පාරම්පරික කලා චාරිත්‍රයකි."),
        q("උඩරට පා සරඹ පුහුණු වන විට පාද පොළොවෙන් ඔසවන උස ප්‍රමාණය විය යුත්තේ කෙසේද?", "තාලයට අනුව දණහිස් මට්ටම ආසන්නයට සමබරව", "කොන්දට ඉහළින් පිටුපසට", "මිලිමීටරයක් පමණ පොළොව අසලින්", "කිසිසේත්ම නොඔසවා", "පා සරඹවලදී පාදය නිවැරදි උසට ඔසවා නැවත තාලයට පොළොවට තැබිය යුතුය."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාසවලදී අත්ල හරවන ආකාරය හඳුන්වන්නේ කුමන නමකින්ද?", "අත් පෙරළීම හෙවත් මැණික් කටු කරකැවීම", "ඇඟිලි ගැටගැසීම", "අත්ල සැඟවීම", "මිට මොළවා ගැසීම", "මැණික් කටුව මෘදුව කරකවා අත්ල ඇතුළට හා පිටතට හැරවීම උඩරට සුන්දරත්වයයි."),
        q("කොහොඹා කංකාරියේදී වෙස් නැට්ටුවන් විසින් ඉදිරිපත් කරන 'අස්න' නමැති කොටසින් සිදු කරන්නේ කුමක්ද?", "පඬුවස්දෙව් හා කුවේණි පුවත ගායනාත්මකව ප්‍රකාශ කිරීම", "ප්‍රේක්ෂකයන්ට ආහාර බෙදීම", "නැටුම් ශාලාව අලුත්වැඩියා කිරීම", "වෙස්මුහුණු පින්තාරු කිරීම", "කුවේණි අස්න, හංස අස්න ආදිය කංකාරියේ ප්‍රබල සාහිත්‍යමය හා නර්තන අංග වේ."),
        q("උඩරට නර්තන කලාවේ 'තාල පද' ඉගෙන ගැනීමේදී 'තත් තොං නං' යන අක්ෂර හැඳින්වෙන්නේ කුමන නමකින්ද?", "මූලික බීජාක්ෂර හෙවත් තාල පද", "සංස්කෘත ව්‍යාකරණ සූත්‍ර", "වන්නම් කවි එළිසම පද", "සාම්ප්‍රදායික ගද්‍ය වාක්‍ය", "ගැටබෙරයේ හා නැටුමේ මූලික නාද උපදවන අක්ෂර මේවා වේ."),
        q("උඩරට වෙස් නැට්ටුවාගේ 'හඟල' නමැති රෙද්දේ පිටුපසින් ඉණ හරහා සවි කරන පටිය කුමක්ද?", "පටිස්ථානය හෙවත් ඉණ පටිය", "තෝඩු යුගලය", "බුබුළු මාලය", "නළල් පටිය", "පැනුම් හා කැරකිලිවලදී වස්ත්‍රය ස්ථාවරව තබා ගැනීමට මෙය ඉවහල් වේ."),
        q("උඩරට 'නෛයන්ඩි' නැටුමේදී දැකිය හැකි ප්‍රධාන නර්තන අංග මොනවාද?", "වන්නම්, සරඹ, කස්තිරම් හා අඩව්", "දහඅට සන්නියේ රෝග ලක්ෂණ", "කෝලම් ලෙන්චිනා චරිතය", "රබන් කැරකවීම පමණි", "වෙස් තට්ටුව නොමැතිව නමුත් උඩරට නර්තනයේ මූලික කලා අංග නෛයන්ඩි නැටුමේදී රඟ දැක්වේ."),
        q("උඩරට නැටුම් ශිල්පියෙකුගේ 'දෙපා පිහිටීම' හෙවත් මණ්ඩියේදී පාද ඇඟිලි යොමු කළ යුතු දිශාව කුමක්ද?", "දෙපසට අංශක 45 කට වඩා විවෘත වන සේ", "එකිනෙක ගැටෙන සේ ඇතුළට", "පිටුපසට සම්පූර්ණයෙන් හරවා", "ඉහළ අහසට ඔසවා", "පාද ඇඟිලි දෙපසට හැරවීමෙන් දණහිස් නිවැරදි මණ්ඩි හැඩයට නැමේ."),
        q("උඩරට නර්තන ක්ෂේත්‍රයේ 'ගැටබෙරය' වාදනය කිරීමේදී යොදාගන්නා ප්‍රධාන වාදන ඉරියව් දෙක මොනවාද?", "සිටගෙන ඉණේ බැඳ වැයීම සහ බිම හිඳගෙන වැයීම", "පුටුවක හිඳ පාදයෙන් වැයීම", "දිගා වී හිස මත තබා වැයීම", "ජලයේ බැස සිට වැයීම", "පෙරහැරේ හා වේදිකාවේ සිටගෙනත් පුහුණුවීම්වලදී හිඳගෙනත් ගැටබෙරය වයනු ලැබේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' පිළියෙළ කිරීමේදී සැමවිටම සුදු රෙදිවලට මුල් තැන දෙන්නේ ඇයි?", "පවිත්‍රතාව, පූජනීයත්වය හා රිදී ආභරණ කැපී පෙනීම සඳහා", "රෙදි සේදීම වැළැක්වීමට", "අඳුරේ නොපෙනී සිටීමට", "වෙනත් වර්ණ නොමැති නිසා", "සුදු හා රතු වර්ණ සමඟ රිදී පැහැ ආභරණ උසස් දෘශ්‍ය අලංකාරයක් මවයි."),
        q("උඩරට නැටුමේදී 'තීර්මාන' පදයකදී 'තක දොං තක දොං තා' වැනි අවසාන හඬ සමඟ නැට්ටුවා සිදු කරන්නේ කුමක්ද?", "ප්‍රබල පාද පහරක් තබා ස්ථාවර ඉරියව්වකින් නතර වීම", "වේදිකාවෙන් පැන දුව යාම", "හිඳගෙන විවේක ගැනීම", "අත්පුඩි ගැසීම", "තීර්මානය නිම වන විට බෙර හඬ හා නැට්ටුවාගේ ඉරියව්ව එකවර නතර වේ."),
        q("උඩරට 'පන්තේරු' නැටුමේදී පන්තේරුව උඩට දමා අල්ලා ගැනීමට නැට්ටුවා තුළ තිබිය යුතු ප්‍රධාන කුසලතාව කුමක්ද?", "දෑස් හා දෑත් අතර තියුණු සම්බන්ධීකරණය හා තාල අවබෝධය", "අධික ශබ්දයෙන් කෑගැසීම", "බිම වැතිරීම", "දෑස් පියාගැනීම", "ගුවනේ කැරකෙන පන්තේරුව තාලයටම අල්ලා ගැනීම දක්ෂතාවකි."),
        q("උඩරට නර්තන පුහුණුවේදී ශිෂ්‍යයන් 'කටපාඩම්' කළ යුතු වැදගත්ම මූලික කොටස කුමක්ද?", "සරඹ පද, වන්නම් කවි සහ තාල ප්‍රස්තාර", "බටහිර ඔපෙරා ගීත හා වයලීන් සටහන්", "වේදිකා ආලෝක පුවරු හා විදුලි සටහන්", "ප්‍රේක්ෂක ශාලා ආසන අංක හා පිළිවෙළ", "තාල පද හා කවි මතකයේ තිබීම නිවැරදි නර්තනයට මඟ පෙන්වයි."),
        q("උඩරට වෙස් නැට්ටුවාගේ 'කරපටිය' සහ 'අවුල්හැරය' අතර ඇති සම්බන්ධය කුමක්ද?", "කරපටිය ගෙලේත් අවුල්හැරය පපුව හරහාත් පළඳියි", "දෙකම දෙපා වළලුකරේ සිළම්බු සමඟ පළඳියි", "දෙකම ගැටබෙරයේ වරපටිය මත බඳිනු ලැබේ", "දෙකම වෙස් තට්ටුවේ පත් අතර සවි කරනු ලැබේ", "මෙම ආභරණ දෙකම උඩුකය අලංකාර කරන ප්‍රධාන කොටස් වේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් පූජාව' හෝ 'පහන් දැල්වීම' සිදු කරන්නේ කුමන ස්ථානයක් අභියසද?", "බුදුන් හා මලය රජු ඇතුළු දේව පිළිරූ හෝ පහන අභියස", "ගමේ පොදු ක්‍රීඩා පිටියක් මැද", "පාසල් පුස්තකාල ශාලාව තුළ", "නාට්‍ය වේදිකාවට පිටුපස ගබඩාව තුළ", "වෙස් ආභරණ පැළඳීමට පෙර භක්තියෙන් ආශිර්වාද ලබාගැනීම සිරිතකි."),
        q("උඩරට නැටුමේ 'පද අල්ලා ගැනීම' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "ගැටබෙර වාදකයා වයන තාල පදයට අනුව නැට්ටුවාගේ පාද හා අත් ගැළපීම", "බිම වැටුණු බෙරය ඇහිඳීම", "වෙස් තට්ටුව පෙට්ටියකට දැමීම", "කවි පොත අතින් අල්ලා ගැනීම", "බෙර හඬට ක්ෂණිකව ප්‍රතිචාර දක්වමින් නැටීම දක්ෂ නැට්ටුවාගේ ලක්ෂණයකි."),
        q("උඩරට සම්ප්‍රදායේ 'නෛයන්ඩි' නැට්ටුවෙකුට වෙස් තට්ටුව පැළඳීමේ අවස්ථාව හිමි වන්නේ කුමන උත්සවයෙන් පසුවද?", "වෙස් මංගල්‍යයෙන් පසුව", "සොකරි නාටකයෙන් පසුව", "සිංහල අවුරුදු උත්සවයෙන් පසුව", "කළගෙඩි නැටුමෙන් පසුව", "නිසි පුහුණුව සම්පූර්ණ කර වෙස් මංගල්‍යය ලැබූ පසු වෙස් නැටුමට සුදුසුකම් ලබයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'සළු නැටුම' ඉදිරිපත් කිරීමේදී ශිල්පියා සතුට හා ලාලිත්‍යය ප්‍රකාශ කරන්නේ කුමන චලන තුළින්ද?", "සුදු සළුව කරකවමින් හා රළ නංවමින් කරන මෘදු අත් චලන", "කඩු ගසන රළු චලන", "දෙපා බිම දිගේ ඇදීම", "නිශ්චලව වාඩි වී සිටීම", "සුළඟේ පාවෙන සළුව නැටුමේ සෞම්‍ය ගුණය ඉස්මතු කරයි."),
        q("උඩරට නැටුමේදී 'පිනුම්' ගැසීමේදී දණහිස් නමා පොළොවෙන් ඉහළට පනින්නේ ඇයි?", "පොළොවට පතිත වන විට සන්ධිවලට ඇතිවන පීඩනය අවම කර ගැනීමට", "ප්‍රේක්ෂකයන් බිය ගැන්වීමට", "පාවහන් ගලවා දැමීමට", "හිස් වැසුම බිම දැමීමට", "මණ්ඩිය නැවීම ස්ප්‍රිං එකක් මෙන් ක්‍රියා කර සිරුරේ ආබාධ වළකයි."),
        q("උඩරට සම්ප්‍රදායේ 'අවුල්හැරය' පළඳින ආකාරයෙන් හැඳින්වෙන හැඩය කුමක්ද?", "පපුව හරහා කතිර හැඩයට හෝ ජාලාකාරව විහිදෙන හැඩය", "තනි සිරස් ඉරක හැඩය", "වළලුකර වටා යන හැඩය", "හිස පිටුපස කොණ්ඩ ගැටයක හැඩය", "රන් හෝ රිදී බොත්තම් සමඟ උඩුකය පුරා අවුල්හැරය විහිදී පවතී."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අතරින් 'අත් මාරුව' පුහුණුවේදී වැදගත් වන අතේ කොටස කුමක්ද?", "මැණික් කටුව සහ ඇඟිලි තුඩු", "වැලමිට පමණි", "උරහිස් පමණි", "නියපොතු පමණි", "මැණික් කටුව මෘදුව කැරකැවීමෙන් උඩරට හස්ත චලනවල අලංකාරය මතු වේ."),
        q("උඩරට 'වෙස් ඇඳුම' නිර්මාණය කිරීමේදී යොදාගන්නා ප්‍රධාන වර්ණ තුන මොනවාද?", "සුදු, රතු සහ රිදී පැහැය", "නිල්, කොළ සහ කළු පැහැය", "තැඹිලි, දම් සහ අළු පැහැය", "කහ, දුඹුරු සහ රෝස පැහැය", "සුදු වස්ත්‍රය, රතු පටි හා රිදී ආභරණ උඩරට සම්ප්‍රදායේ දෘශ්‍ය අනන්‍යතාවයි."),
        q("උඩරට නර්තන ක්ෂේත්‍රයේදී 'පහත් මණ්ඩිය' යොදා ගනු ලබන ප්‍රධාන නැටුම් අවස්ථාව කුමක්ද?", "ප්‍රබල අඩව්, කස්තිරම් හා ගාම්භීර ඉරියව් පෙන්වන විට", "නැටුම ආරම්භයට පෙර විවේක ගන්නා විට", "ගායනය පමණක් කරන විට", "පෙරහැරේ ඇවිද යන විට", "පොළොවට සමීපව මණ්ඩිය නැමීමෙන් නැටුමේ ශක්තිය හා පාලනය ප්‍රදර්ශනය වේ."),
        q("උඩරට 'උඩැක්කි' නැටුමේදී ගායනා කරනු ලබන කවි බොහෝ විට අයත් වන්නේ කුමන වර්ගයටද?", "දේව ස්තෝත්‍ර, ප්‍රශස්ති හා සෞන්දර්යාත්මක කවි", "කෘෂිකාර්මික පැල් කවි", "විදේශීය නාවික ගීත", "ළමා නැළවිලි ගී", "උඩැක්කි කවි ගායනය මිහිරි නාද රටාවලින් යුක්ත වේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් තට්ටුව' හිස මත ස්ථිරව රඳවා ගැනීම සඳහා පිටුපසින් භාවිත කරන ආධාරකය කුමක්ද?", "රෙදි හා නූල් පටි මගින් ජටාවට තදින් බැඳීම", "මැලියම් වර්ග ආලේප කිරීම", "කම්බි ඇණ ගැසීම", "අතින් අල්ලාගෙන නැටීම", "වේගවත් කැරකිලිවලදී පවා නොවැටෙන සේ වෙස් තට්ටුව සීරුවෙන් හිසේ බඳිනු ලැබේ."),
        q("උඩරට නැටුමේදී 'පා සරඹ' අභ්‍යාස මාලාව තුළින් ශිෂ්‍යයෙකු ලබන මානසික හා ශාරීරික ප්‍රතිලාභය කුමක්ද?", "අවධානය, ඉවසීම, දරාගැනීමේ ශක්තිය හා රිද්ම සංවේදීතාව", "ඉක්මන් කෝපය හා නොඉවසිල්ල", "නිදිමත ගතිය", "මාංශපේශී දුර්වල වීම", "ක්‍රමානුකූල පා සරඹ පුහුණුව නැට්ටුවාගේ කායික හා මානසික විනය ගොඩනඟයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාස අවසන් කිරීමේදී නැට්ටුවා සිටගන්නා අවසාන ඉරියව්ව කුමක්ද?", "සමබර මණ්ඩි ඉරියව්වෙන් දෑත් විහිදා නතර වීම", "එක් කකුලක් ඔසවාගෙන වටයක් ඇවිද යාම", "පසුපස හැරී වේදිකාව මත හිඳගැනීම", "දෑත් පහත හෙළා බිම දිගා වී සිටීම", "සෑම සරඹයක්ම තාලයේ 'සම' ස්ථානයේදී ස්ථාවර මණ්ඩියෙන් නිම වේ."),
        q("උඩරට වෙස් ඇඳුමේ 'පිත්තල හෝ රිදී පටි' ශරීරයට හානි නොවන සේ අඳින්නේ කෙසේද?", "යටින් ඝන සුදු රෙදි හා අත් කොට හැට්ටයක් හෝ පටි යොදා ආරක්ෂා කිරීමෙන්", "සම මත කෙලින්ම තියුණු ලෝහ ගැටගැසීමෙන්", "තෙල් ආලේප කිරීමෙන් පමණක්", "කඩදාසි ඔතා ගැනීමෙන්", "වේගවත් චලනවලදී ආභරණ සමේ නොඇතිල්ලෙන සේ යටි ඇඳුම් සකසයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'වෙස් නැට්ටුවා' රංගනයේදී මුහුණේ හැඟීම් පෙන්වීම සඳහා යොදා ගන්නේ කුමක්ද?", "ඇස්, ඇහිබැම හා සෞම්‍ය මුහුණු අභිනය", "වෙස්මුහුණකින් මුහුණ සම්පූර්ණයෙන් වැසීම", "කතා කරමින් විහිළු කිරීම", "මුහුණ දෑතින් වසා ගැනීම", "උඩරට නැට්ටුවා වෙස්මුහුණු නොදමන අතර තම සජීවී මුහුණෙන් භාව ප්‍රකාශ කරයි."),
        q("උඩරට නැටුමේදී 'තාලම්පට' වාදකයා නොමැති අවස්ථාවක රිද්මය පාලනය කර ගන්නේ කුමන ශබ්දය ආධාරයෙන්ද?", "ගැටබෙරයේ වාදන පද හා නැට්ටුවාගේ සිළම්බු හඬ", "ප්‍රේක්ෂකයන්ගේ හුස්ම ගැනීම", "පිටතින් එන සුළං හඬ", "විදුලි සීනු නාදය", "ගැටබෙරයේ 'තෙයි' හා 'තත්' නාද තාලය රඳවා ගැනීමට මඟ පෙන්වයි."),
        q("උඩරට පා සරඹ පුහුණු වන ආධුනිකයන් 'දණ්ඩියම' ස්පර්ශ කරන නිවැරදි ආකාරය කුමක්ද?", "දෙඅත් උරහිස් පළලට තබා මෘදුව එහෙත් ස්ථාවරව අල්ලා ගැනීම", "දණ්ඩියම මත වාඩි වීම", "එක් ඇඟිල්ලකින් පමණක් ඇල්ලීම", "දණ්ඩියම ඔසවා කරේ තබා ගැනීම", "අත් දෙකේ බර දණ්ඩියම මත නොදමා සමබරතාව සඳහා පමණක් එය අල්ලාගෙන සිටිය යුතුය."),
        q("උඩරට සම්ප්‍රදායේ 'සිළම්බු' යුගලය වළලුකරේ බඳින විට සැලකිලිමත් විය යුතු කරුණ කුමක්ද?", "නැටුම අතරතුර නොගැලවෙන පරිදි එහෙත් රුධිර ගමනාගමනයට බාධා නොවන සේ බැඳීම", "වළලුකර සිදුරු වන තරම් තදින් බැඳීම", "කකුලෙන් ගිලිහී වැටෙන සේ බුරුලෙන් දැමීම", "දණහිස් මත බැඳීම", "නැට්ටුවාගේ ආරක්ෂාව හා සිළම්බු හඬ නිවැරදිව ලබාගැනීමට මෙය වැදගත් වේ."),
        q("උඩරට නර්තන ක්ෂේත්‍රයේ 'වෙස් ඇඳුම' හා සම්බන්ධ 'රාජකීය පෙනුම' ඇති කිරීමට බෙහෙවින් ඉවහල් වන කොටස් දෙක මොනවාද?", "වෙස් තට්ටුව සහ උළුදය සහිත රැළි මාලය", "අත් රබාන සහ කුල්ල", "සන්නි මුහුණ සහ පන්දම", "ලී කෙළි සහ කළගෙඩිය", "මෙම විචිත්‍ර හිස් පළඳනාව හා ඉණ වස්ත්‍රය උඩරට නැටුමේ ප්‍රෞඪත්වය මවයි."),
        q("උඩරට නැටුමේදී 'ගොඩ සරඹ' අභ්‍යාස මාලාව තුළින් ශිෂ්‍යයාගේ ඉදිරි වන්නම් පුහුණුවට ලැබෙන පිටිවහල කුමක්ද?", "සංකීර්ණ අත්-පා චලන, කැරකිලි හා කස්තිරම් පහසුවෙන් ග්‍රහණය කරගැනීම", "කවි පොත් මුද්‍රණය කිරීමට ඉගෙනීම", "බෙර හම් මැසීමට ඉගෙනීම", "වේදිකා තිර ඇඳීමට ඉගෙනීම", "මූලික ගොඩ සරඹ 12 මනාව ප්‍රගුණ කළ ශිෂ්‍යයාට ඕනෑම වන්නමක් පහසුවෙන් නැටිය හැකිය."),
        q("උඩරට නර්තනයේ 'කවිකාර මඩුව' හා සම්බන්ධ ප්‍රශස්ති ගායන සම්ප්‍රදායෙන් වන්නම්වලට ලැබුණේ කුමක්ද?", "ශාස්ත්‍රීය සාහිත්‍යමය වටිනාකම හා මිහිරි කවි ව්‍යුහය", "වෙස්මුහුණු කැපීමේ ක්‍රම", "පහතරට තාල පද", "බටහිර ස්වර ප්‍රස්තාර", "උසස් සිංහල හා සංස්කෘත මිශ්‍ර කවි භාෂාවක් වන්නම් තුළ දක්නට ලැබේ."),
        q("උඩරට නැටුමේ 'පා සරඹ' අභ්‍යාස කරන විට පාද පොළොවට තැබීමෙන් නැඟෙන ශබ්දය පැහැදිලි විය යුත්තේ ඇයි?", "පියවරවල තාල නිරවද්‍යතාව හා ශක්තිය තහවුරු කර ගැනීමට", "පොළොව සිදුරු කිරීමට", "අසල්වැසියන්ට බාධා කිරීමට", "පාද තුවාල කර ගැනීමට", "විළුඹ හා යටිපතුල ස්ථිරව තැබීමෙන් රිද්මය මැනවින් ප්‍රකට වේ."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'වෙස් ඇඳුම' කෞතුකාගාර හා කලා ආයතනවල සංරක්ෂණය කිරීමේදී මූලික වන්නේ කුමක්ද?", "දේශීය හස්ත කර්මාන්ත ශිල්පීය දැනුම හා රිදී වැඩ පරම්පරා රැකගැනීම", "ප්ලාස්ටික් වෙස් තට්ටු පමණක් සෑදීම", "සියලු ආභරණ උණු කර දැමීම", "රතු රෙදි වෙනුවට කළු රෙදි දැමීම", "සාම්ප්‍රදායික කර්මාන්ත ශිල්පීන්ගේ දැනුම වෙස් කට්ටල නිර්මාණයට අත්‍යවශ්‍ය වේ."),
        q("උඩරට නැටුමේදී 'අඩි ගැසීම' සහ 'පැනුම්' අතරතුර නැට්ටුවාගේ හිස තිබිය යුතු ආකාරය කුමක්ද?", "ඉහළට නෙරා යන සෘජු බවකින් හා සමබරව", "නිතර බිමට කඩා වැටෙන ලෙස", "දෙපසට වැනෙමින්", "උරහිස් අතර සඟවාගෙන", "සිරුර කෙළින් පවත්වා ගැනීම වෙස් තට්ටුවේ තේජස හා නැටුමේ සෘජු බව සුරකියි."),
        q("උඩරට නර්තන ශිල්පියෙකු තම පුහුණු දිනවලදී 'තාල පද' හඬ නඟා කියවීමෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "සවන්දීමේ හා චලන රිද්ම මතකය ශක්තිමත් වීම", "කටහඬ අහිමි වීම", "පාද චලන නතර වීම", "තාලය අමතක වීම", "මුවින් කියන රිද්මය සිරුරේ චලන සමඟ ක්ෂණිකව සම්බන්ධ වේ."),
        q("උඩරට නර්තන ක්ෂේත්‍රයේ 'ගුරු බැතිමත්කම' ප්‍රකාශ වන සාම්ප්‍රදායික අවස්ථාවක් කුමක්ද?", "පුහුණුව ආරම්භයේදී හා අවසානයේදී ගුරුවරයාගේ දෙපා නැමදීම", "පුහුණු ශාලාවෙන් හොරෙන් පිටවීම", "බෙරය මත හිඳ ගැනීම", "ගුරුවරයාට පිටුපා යාම", "නර්තන කලායතනවල අදටත් මෙම ගෞරවනීය සිරිත පවත්වාගෙන යනු ලැබේ."),
        q("උඩරට නර්තන සම්ප්‍රදාය පිළිබඳව සඳහන් කරන විට 'මහනුවර පෙරහැර' සමඟ නොබිඳෙන සබඳතාවක් ඇති නර්තන අංගය කුමක්ද?", "වෙස් නැටුම, පන්තේරු නැටුම සහ උඩැක්කි නැටුම", "කෝලම් හා සොකරි නැටුම", "දහඅට සන්නිය", "බටහිර ටැප් ඩාන්ස්", "මෙම ත්‍රිවිධ උඩරට නැටුම් අංග දළදා පෙරහැරේ ප්‍රෞඪත්වය ඉහළ නංවයි."),
        q("උඩරට 'නෛයන්ඩි' නැටුමේදී ශිල්පියා විසින් උඩුකය ආවරණය කිරීමට භාවිත නොකරන ආභරණය කුමක්ද?", "වෙස් තට්ටුව", "අවුල්හැරය", "සිළම්බු", "තලප්පාව", "වෙස් තට්ටුව වෙස් නැට්ටුවන්ට පමණක් වෙන් වූ ශීර්ෂාභරණයකි."),
        q("උඩරට නැටුමේදී 'තාලය අල්ලාගෙන සිටීම' සඳහා නැට්ටුවා භාවිත කරන ප්‍රධාන මානසික කුසලතාව කුමක්ද?", "අවධානය සහ මාත්‍රා ගණනය කිරීමේ සංවේදීතාව", "වේදිකාවේ මිල ගණන් කිරීම", "ප්‍රේක්ෂකයන් ගණන් කිරීම", "කාලගුණය පරීක්ෂා කිරීම", "නිහඬව හිත තුළින් ලය හා ආවර්තන ගණනය කිරීම නැට්ටුවාට අත්‍යවශ්‍ය වේ."),
        q("උඩරට වෙස් ඇඳුමේ 'පටි' සහ 'ආභරණ' කට්ටලය පූර්ණ වීමෙන් නැට්ටුවා තුළ ඇතිවන මානසික තත්ත්වය කුමක්ද?", "කලාව කෙරෙහි ආත්ම විශ්වාසය හා පූජනීය ගෞරවය", "ලැජ්ජාව හා බිය", "නැටුමෙන් ඉවත් වීමේ ආශාව", "විඩාව හා කෝපය", "වෙස් ඇඳුම පැළඳීමත් සමඟම නැට්ටුවා තුළ විශේෂිත ප්‍රෞඪ චරිත ස්වභාවයක් ආරෝපණය වේ.")
    )
}
